using System;
using Outbreak.Contracts;
using Outbreak.Core;
using Outbreak.Persistence;
public static partial class Program
{
    private static void CheckSupplyDeliveryCases()
    {
        Check("Supply couriers walk between shelter boxes and deliver conserved food",()=>{
            World world=EncounterScenarios.SupplyDeliveryTest();world.Step();Require(world.SupplyDeliveriesEnabled && world.ActorAt(0).restockPhase==RestockPhase.Collecting && world.ActorAt(0).restockSourceBox==73 && world.ActorAt(0).restockBox==65 && world.FoodSupplies().SupplyDeliveries==1,"Courier did not assign a known donor and separate recipient box.");Require(SupplyRoom(world,63).IncomingDeliveries==1 && SupplyRoom(world,72).OutgoingDeliveries==1 && SupplyRoom(world,63).BoxMeals==0,"Shortage overview omitted assigned delivery or counted undelivered cargo as stock.");World copy=Documents.ParseSave(State(world));for(int i=0;i<350 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)<2;i++){world.Step();copy.Step();Require(State(world)==State(copy),"Supply delivery diverged after saving.");}Require(StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==2 && StorageRules.Count(world.StorageBoxAt(12,3),InventoryItem.Food)==10 && world.ActorAt(0).carriedFood==1 && world.FoodSupplies().RemainingMeals==13,"Courier failed to deliver food, retain personal meals or conserve total supplies.");Require(world.ActorAt(0).restockPhase==RestockPhase.None && world.ActorAt(0).restockSourceBox==0 && world.ActorAt(0).energySpent>0 && world.TerrainAt(5,5)==Terrain.DoorClosed && world.TerrainAt(10,5)==Terrain.DoorClosed,"Delivery failed cleanup, movement energy or physically closing shelter doors.");
        });
        Check("Only remembered surplus in a different shelter can start a delivery",()=>{
            foreach(int mode in new[]{0,1,2,3}){SaveDocument saved=EncounterScenarios.SupplyDeliveryTest().Capture();if(mode==0)saved.actors[0].storageMemory=new[]{saved.actors[0].storageMemory[0]};if(mode==1)saved.actors[0].storageMemory[1].food=6;if(mode==2)saved.actors[0].hunger=80;if(mode==3)saved.actors[0].energySpent=50;World world=World.Restore(saved);world.Step();Require(world.ActorAt(0).restockSourceBox==0,"Unknown, at-reserve or unsafe donor trip was assigned (mode "+mode+").");}
        });
        Check("Couriers recheck donor reserves at pickup without learning hidden stock changes",()=>{
            SaveDocument saved=EncounterScenarios.SupplyDeliveryTest().Capture();World full=World.Restore(saved);saved.map.storageBoxes[1].items[0].quantity=6;World depleted=World.Restore(saved);Run(full,20);Run(depleted,20);Require(Documents.Encode(full.ActorAt(0))==Documents.Encode(depleted.ActorAt(0)),"Courier learned hidden donor depletion before leaving home.");for(int i=0;i<300;i++){depleted.Step();Require(StorageRules.Count(depleted.StorageBoxAt(12,3),InventoryItem.Food)>=6,"Courier depleted the donor below its reserve.");}Require(StorageRules.Count(depleted.StorageBoxAt(4,3),InventoryItem.Food)==0 && depleted.ActorAt(0).restockSourceBox==0 && depleted.FoodSupplies().RemainingMeals==7,"Stale donor memory created food or repeated an exhausted surplus job.");
        });
        Check("Saved return cargo survives target cancellation without lost or duplicated food",()=>{
            World world=EncounterScenarios.SupplyDeliveryTest();for(int i=0;i<220 && world.ActorAt(0).restockPhase!=RestockPhase.Returning;i++)world.Step();Require(world.ActorAt(0).restockPhase==RestockPhase.Returning && world.ActorAt(0).carriedFood==3,"Could not reach delivery cargo phase.");Require(world.TrySetStorageFoodReserve(4,3,0),"Could not stop recipient reserve.");World copy=Documents.ParseSave(State(world));for(int i=0;i<220 && world.ActorAt(0).restockPhase!=RestockPhase.None;i++){world.Step();copy.Step();}Require(State(world)==State(copy) && world.FoodSupplies().RemainingMeals==13 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==2 && StorageRules.Count(world.StorageBoxAt(12,3),InventoryItem.Food)==10,"Recipient cancellation lost cargo or failed saved return behavior.");
        });
        Check("Concurrent delivery pickups cannot remove a donor reserve",()=>{
            WorldMap map=new WorldMap(20,22);AddDeliveryRoom(map,1,2);AddDeliveryRoom(map,1,13);AddDeliveryRoom(map,10,2);foreach(int y in new[]{3,14})map.SetStorageBox(new StorageBoxDocument{x=4,y=y,capacity=30,items=new ItemStackDocument[0]});map.SetStorageBox(new StorageBoxDocument{x=12,y=3,capacity=30,items=new[]{new ItemStackDocument{item=InventoryItem.Food,quantity=8}}});World world=new World(map,214,encounter:true,hunger:true);int id;world.TrySpawn(Species.Human,11,3,out id);world.TrySpawn(Species.Human,12,4,out id);SaveDocument saved=world.Capture();for(int i=0;i<2;i++){saved.actors[i].carriedFood=1;saved.actors[i].hunger=10;saved.actors[i].shelterId=72;saved.actors[i].shelterX=saved.actors[i].x;saved.actors[i].shelterY=saved.actors[i].y;saved.actors[i].shelterState=ShelterState.Inside;saved.actors[i].restockHomeId=i==0?63:283;saved.actors[i].homeShelterId=saved.actors[i].restockHomeId;saved.actors[i].restockBox=i==0?65:285;saved.actors[i].restockSourceBox=73;saved.actors[i].restockPhase=RestockPhase.Collecting;saved.actors[i].restockUntilTick=600;saved.actors[i].storageMemory=new[]{new StorageMemoryRecord{x=12,y=3,food=8,space=22,observedTick=0}};}world=World.Restore(saved);Run(world,2);Require(StorageRules.Count(world.StorageBoxAt(12,3),InventoryItem.Food)==6 && world.ActorAt(0).carriedFood==3 && world.ActorAt(1).carriedFood==1 && world.FoodSupplies().RemainingMeals==10,"Competing couriers took reserved food or duplicated surplus.");
        });
        Check("A zombie revealed at the donor door stops collection and closes the inspection door",()=>{
            World world=EncounterScenarios.SupplyDeliveryTest();int id;Require(world.TrySpawn(Species.Zombie,12,5,out id),"Could not place donor room threat.");for(int i=0;i<180 && world.ActorAt(0).restockPhase!=RestockPhase.Returning;i++)world.Step();Require(world.ActorAt(0).restockPhase==RestockPhase.Returning && world.ActorAt(0).rejectedShelterId==72 && world.ActorAt(0).carriedFood==1 && StorageRules.Count(world.StorageBoxAt(12,3),InventoryItem.Food)==12 && world.TerrainAt(10,5)==Terrain.DoorClosed,"Courier ignored revealed danger, collected food or left its inspection door open.");
        });
        Check("Couriers keep their own meals when hunger interrupts a loaded return",()=>{
            World world=EncounterScenarios.SupplyDeliveryTest();for(int i=0;i<220 && world.ActorAt(0).restockPhase!=RestockPhase.Returning;i++)world.Step();SaveDocument saved=world.Capture();saved.actors[0].hunger=80;world=World.Restore(saved);for(int i=0;i<160 && world.ActorAt(0).restockPhase!=RestockPhase.None;i++)world.Step();Require(world.ActorAt(0).hunger<40 && world.ActorAt(0).carriedFood==1 && StorageRules.Count(world.StorageBoxAt(4,3),InventoryItem.Food)==1 && StorageRules.Count(world.StorageBoxAt(12,3),InventoryItem.Food)==10 && world.FoodSupplies().RemainingMeals==12,"Hungry courier delivered personal food, lost cargo or failed to conserve one eaten meal.");
        });
        Check("Delivery source validation infection and old rules preserve task boundaries",()=>{
            World world=EncounterScenarios.SupplyDeliveryTest();world.Step();string before=State(world);Action<Action<SaveDocument>> bad=change=>{SaveDocument saved=world.Capture();change(saved);Reject(()=>World.Restore(saved));};bad(s=>s.actors[0].restockSourceBox=-1);bad(s=>s.actors[0].restockSourceBox=65);bad(s=>s.actors[0].restockSourceBox=1);bad(s=>s.rulesVersion=EncounterRules.BoxReportsVersion);Require(State(world)==before,"Rejected delivery save changed live state.");SaveDocument infected=world.Capture();infected.actors[0].turnAtTick=100;world=World.Restore(infected);world.Step();Require(world.ActorAt(0).restockPhase==RestockPhase.None && world.ActorAt(0).restockSourceBox==0,"Infection retained supply delivery assignment.");SaveDocument old=EncounterScenarios.SupplyDeliveryTest().Capture();old.rulesVersion=EncounterRules.BoxReportsVersion;world=World.Restore(old);world.Step();Require(!world.SupplyDeliveriesEnabled && world.BoxReportsEnabled && world.ActorAt(0).restockPhase==RestockPhase.None,"Earlier box-report rules silently gained inter-shelter deliveries.");
        });
    }
    private static void AddDeliveryRoom(WorldMap map,int left,int top)
    {
        for(int y=top;y<=top+6;y++)for(int x=left;x<=left+4;x++)map.Set(x,y,x==left || x==left+4 || y==top || y==top+6?Terrain.Wall:Terrain.Floor);map.Set(left+4,top+3,Terrain.DoorClosed);
    }
}
